/bin/bash -lc "node -e '
const base=\"http://localhost:8080\";
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
let token=null, tokenFetches=0, retries=0;
async function renew(){const r=await fetch(base+\"/token\",{method:\"POST\"}); if("'!r.ok) throw new Error("token "+r.status); token=(await r.json()).token; tokenFetches++;}
function retryMs(r,b){const h=r.headers.get("retry-after"); if(h && /''^'"\\\\d+(\\\\.\\\\d+)?"'$/.test(h)) return Math.ceil(Number(h)*1000); return b;}
async function api(path){let attempt=0; for(;;){if(!token) await renew(); let r; try {r=await fetch(base+path,{headers:{Authorization:"Bearer "+token}});} catch(e){if(++attempt>12) throw e; retries++; await sleep(Math.min(1000*attempt,10000)); continue;} if(r.status===401){token=null; if(++attempt>12) throw new Error("repeated unauthorized "+path); retries++; continue;} if(r.status===429){if(++attempt>20) throw new Error("repeated rate limit "+path); retries++; await sleep(retryMs(r,1000)); continue;} if(r.status>=500){if(++attempt>12) throw new Error("server "+r.status+" "+path); retries++; await sleep(retryMs(r,1000*attempt)); continue;} if(!r.ok) throw new Error("HTTP "+r.status+" "+path+" "+await r.text()); return r.json();}}
(async()=>{let page=1,totalPages=null, listings=0,dup=0; const orders=new Map(); for(;;){const d=await api("/orders?page="+page); if(totalPages===null) totalPages=d.total_pages; if(d.page!==page) throw new Error("page mismatch"); for(const o of d.items){listings++; if(orders.has(o.id)) dup++; else orders.set(o.id,o);} if(!d.next) break; page++; if(page>totalPages+1) throw new Error("pagination overflow");} const customers=new Map(); async function customer(id){if(!customers.has(id)) customers.set(id,await api("/customers/"+encodeURIComponent(id))); return customers.get(id);} const start=Date.parse("2025-03-01T00:00:00Z"), end=Date.parse("2025-06-01T00:00:00Z"); let count=0,total=0; const by={north:0,south:0,east:0,west:0}; for(const o of orders.values()){const t=Date.parse(o.placed_at); if(Number.isNaN(t)) throw new Error("invalid timestamp "+o.id); if(o.status!=="shipped"||t<start||t>=end) continue; const c=await customer(o.customer_id); const discounted=Math.floor((o.amount_cents*(100-c.discount_pct)+50)/100); if(!(c.region in by)) throw new Error("region "+c.region); by[c.region]+=discounted; total+=discounted; count++;} if(Object.values(by).reduce((a,b)=>a+b,0)!==total) throw new Error("sum mismatch"); console.log(JSON.stringify({result:{total_cents:total,order_count:count,duplicates_skipped:dup,by_region:by},audit:{pages:page,total_pages:totalPages,listings,distinct_orders:orders.size,customers_cached:customers.size,token_fetches:tokenFetches,retries}},null,2));})().catch(e=>{console.error(e.stack||e);process.exit(1)});
'"'"

